<script setup lang="ts">import {computed} from 'vue';const p=withDefaults(defineProps<{modelValue?:string;mask:string;placeholder?:string;label?:string;required?:boolean;disabled?:boolean}>(),{modelValue:''});const emit=defineEmits<{'update:modelValue':[value:string]}>();const slots=new Set(['#','A','*']);function format(raw:string){const chars=raw.replace(/[^a-zA-Z0-9]/g,'');let output='',idx=0;for(const m of p.mask){if(idx>=chars.length)break;if(slots.has(m)){while(idx<chars.length && !(m==='#'?/[0-9]/:m==='A'?/[a-zA-Z]/:/[a-zA-Z0-9]/).test(chars[idx]))idx++;if(idx<chars.length)output+=chars[idx++]}else output+=m}return output}const hint=computed(()=>p.mask.replace(/#/g,'0').replace(/[A*]/g,'X'))</script><template><label class="vx-field"><span v-if="label" class="vx-field__label">{{label}}</span><input class="vx-control" :value="modelValue" :placeholder="placeholder||hint" :required="required" :disabled="disabled" @input="emit('update:modelValue',format(($event.target as HTMLInputElement).value))"/></label></template>
